style.css:
@-moz-document domain("creator.nightcafe.studio") {
/* 1. Terminal palette and CSS-only hacker grid canvas.
   No embedded wallpaper, base64 images, or external image URLs.
   Grid and scanlines paint only the page background, never artwork. */
html, body {
  background-color: #0a0a0a !important;
  color: #b6ffc5 !important;
  font-family: Consolas, "Lucida Console", "Courier New", monospace !important;
}
body {
  /* Light-green horizontal scanlines, then 40px vertical/horizontal grid. */
  background-image:
    repeating-linear-gradient(to bottom,
      rgba(130, 255, 165, .045) 0px,
      rgba(130, 255, 165, .045) 1px,
      transparent 1px,
      transparent 5px),
    linear-gradient(to right,
      rgba(93, 255, 138, .13) 1px,
      transparent 1px),
    linear-gradient(to bottom,
      rgba(93, 255, 138, .13) 1px,
      transparent 1px) !important;
  background-size: 100% 100%, 40px 40px, 40px 40px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

#root, #__next, #app {
  background-color: transparent !important;
  color: #b6ffc5 !important;
}
main, [role="main"], .MuiContainer-root,
[class*="workspace"], [class*="Workspace"], [class*="page-content"],
[class*="pageContent"], [class*="main-content"], [class*="mainContent"] {
  color: #b6ffc5 !important;
}

/* 2. Readable terminal text on all routes. */
body, button, input, textarea, select, option, label,
nav, aside, [role="tab"], [role="button"], [role="menuitem"],
[role="option"], [role="combobox"], [role="textbox"],
.MuiTypography-root, .MuiButton-root {
  font-family: Consolas, "Lucida Console", "Courier New", monospace !important;
}
h1, h2, h3, h4, h5, h6 {
  color: #bdffca !important;
  font-family: Consolas, "Lucida Console", "Courier New", monospace !important;
  letter-spacing: .3px !important;
  text-shadow: 0 0 8px rgba(0, 255, 102, .25) !important;
}
p, label, legend, summary, time, small, li, dt, dd,
.MuiTypography-root, .MuiFormLabel-root, .MuiInputLabel-root {
  color: #b6ffc5 !important;
}
[class*="text-gray"], [class*="text-grey"], [class*="text-slate"],
[class*="text-zinc"], [class*="text-neutral"], [class*="text-white"] {
  color: #9af0ac !important;
}
a, a:visited, [role="link"] {
  color: #a8ffba !important;
  text-decoration-color: #188044 !important;
}
a:hover, a:focus, [role="link"]:hover {
  color: #00ff66 !important;
  text-decoration-color: #00ff66 !important;
  text-shadow: 0 0 7px rgba(0, 255, 102, .43) !important;
}
a:focus, button:focus, input:focus, textarea:focus, select:focus {
  outline-color: #00ff66 !important;
}

/* 3. Top navigation, drawers, account menus. */
header, [role="banner"], .MuiAppBar-root,
[class*="topbar"], [class*="topBar"], [class*="appHeader"],
[class*="app-header"] {
  background-color: rgba(2, 20, 9, .87) !important;
  border-color: rgba(0, 255, 102, .36) !important;
  border-bottom: 1px solid rgba(0, 255, 102, .46) !important;
  box-shadow: 0 3px 15px rgba(0, 255, 102, .12) !important;
}
nav, aside, [role="navigation"], [role="complementary"],
.MuiDrawer-paper, [data-slot="sidebar"],
[class*="sidebar"], [class*="Sidebar"],
[class*="side-panel"], [class*="sidePanel"] {
  background-color: rgba(3, 22, 10, .82) !important;
  border-color: rgba(0, 255, 102, .26) !important;
  color: #b6ffc5 !important;
}
nav a, nav button, aside a, aside button, header a, header button,
[role="navigation"] a, [role="navigation"] button,
[role="complementary"] a, [role="complementary"] button {
  color: #b6ffc5 !important;
}
nav a:hover, nav button:hover, aside a:hover, aside button:hover,
header a:hover, header button:hover, [role="navigation"] a:hover,
[role="navigation"] button:hover {
  color: #00ff66 !important;
  text-shadow: 0 0 7px rgba(0, 255, 102, .50) !important;
}
[aria-current="page"], [aria-selected="true"] {
  color: #00ff66 !important;
}
header img[alt*="NightCafe"], header img[alt*="nightcafe"],
nav img[alt*="NightCafe"], nav img[alt*="nightcafe"],
header [class*="logo"] svg, header [class*="Logo"] svg {
  filter: drop-shadow(0 0 7px rgba(0, 255, 102, .62)) !important;
}

/* 4. Semi-transparent glass: feed, profiles, creations, studio. */
.MuiPaper-root, .MuiCard-root, .MuiAccordion-root,
[data-slot="card"], article,
[data-testid*="creation-card"], [data-testid*="feed-item"],
[data-testid*="post-card"], [data-testid*="gallery-card"],
[class*="creationCard"], [class*="creation-card"],
[class*="imageCard"], [class*="modelCard"],
[class*="feedCard"], [class*="feed-card"],
[class*="postCard"], [class*="post-card"],
[class*="settingsPanel"], [class*="settings-panel"],
[class*="controlPanel"], [class*="control-panel"],
[class*="glass-panel"] {
  background-color: rgba(5, 28, 13, .69) !important;
  color: #b6ffc5 !important;
  border-color: rgba(0, 255, 102, .24) !important;
  box-shadow: 0 5px 17px rgba(0, 0, 0, .18), inset 0 1px rgba(188, 255, 204, .05) !important;
}
/* Utility-class backgrounds occur on many NightCafe pages. */
[class*="bg-gray-"], [class*="bg-grey-"],
[class*="bg-slate-"], [class*="bg-zinc-"],
[class*="bg-neutral-"], [class*="bg-stone-"],
[class*="bg-white"], [class*="bg-black"] {
  background-color: rgba(5, 28, 13, .72) !important;
}
.MuiCard-root:hover, [data-slot="card"]:hover, article:hover,
[class*="creationCard"]:hover, [class*="feedCard"]:hover,
[data-testid*="creation-card"]:hover, [data-testid*="feed-item"]:hover {
  border-color: rgba(0, 255, 102, .60) !important;
  box-shadow: 0 0 0 1px rgba(0, 255, 102, .15), 0 0 16px rgba(0, 255, 102, .13) !important;
}
.MuiTableContainer-root, [role="grid"],
[class*="gallery-container"], [class*="feed-container"],
[class*="galleryContainer"], [class*="feedContainer"] {
  background-color: transparent !important;
  border-color: rgba(0, 255, 102, .24) !important;
}

/* 5. Dropdowns, popovers, modals, options and tooltips. */
[role="menu"], [role="listbox"], [role="dialog"],
[role="alertdialog"], [role="tooltip"], dialog,
.MuiMenu-paper, .MuiPopover-paper, .MuiDialog-paper,
.MuiAutocomplete-paper, .MuiTooltip-tooltip,
[data-slot="dropdown-menu-content"],
[data-slot="context-menu-content"], [data-slot="select-content"],
[data-slot="popover-content"], [data-slot="dialog-content"],
[data-slot="alert-dialog-content"], [data-slot="sheet-content"],
[data-radix-select-content], [data-radix-menu-content],
[class*="dropdownMenu"], [class*="popoverContent"] {
  background-color: rgba(3, 22, 10, .89) !important;
  color: #b6ffc5 !important;
  border: 1px solid rgba(0, 255, 102, .40) !important;
  box-shadow: 0 12px 35px rgba(0, 0, 0, .44), 0 0 16px rgba(0, 255, 102, .10) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  backdrop-filter: blur(8px) !important;
}
[role="menuitem"], [role="option"],
.MuiMenuItem-root, .MuiListItemButton-root,
[data-slot="dropdown-menu-item"], [data-slot="select-item"],
[data-slot="context-menu-item"] {
  background-color: transparent !important;
  color: #b6ffc5 !important;
}
[role="menuitem"]:hover, [role="menuitem"]:focus,
[role="option"]:hover, [role="option"]:focus,
.MuiMenuItem-root:hover, .MuiListItemButton-root:hover,
[data-slot="dropdown-menu-item"]:hover,
[data-slot="select-item"]:hover, [data-highlighted] {
  background-color: rgba(0, 255, 102, .12) !important;
  color: #00ff66 !important;
}
.MuiBackdrop-root, [data-slot="dialog-overlay"],
[data-slot="sheet-overlay"] {
  background-color: rgba(0, 6, 2, .65) !important;
}

/* 6. Prompt editor, search, forms and creation controls. */
textarea, input[type="text"], input[type="search"],
input[type="email"], input[type="number"], input[type="password"],
input[type="url"], input[type="tel"],
select, [role="textbox"], [role="combobox"],
[contenteditable="true"], .ProseMirror,
.MuiInputBase-root, .MuiOutlinedInput-root,
[data-slot="input"], [data-slot="textarea"] {
  background-color: rgba(2, 19, 9, .80) !important;
  color: #bdffca !important;
  border-color: rgba(0, 255, 102, .40) !important;
  caret-color: #00ff66 !important;
  font-family: Consolas, "Lucida Console", "Courier New", monospace !important;
}
textarea:focus, input[type="text"]:focus, input[type="search"]:focus,
input[type="email"]:focus, input[type="number"]:focus,
select:focus, [role="textbox"]:focus, .ProseMirror:focus {
  border-color: #00ff66 !important;
  box-shadow: 0 0 0 1px rgba(0, 255, 102, .22), 0 0 12px rgba(0, 255, 102, .23) !important;
}
input::placeholder, textarea::placeholder {
  color: #86d79c !important;
  opacity: .82 !important;
}
.MuiSelect-select, .MuiAutocomplete-inputRoot, option {
  background-color: #092915 !important;
  color: #b6ffc5 !important;
}
input[type="checkbox"], input[type="radio"], input[type="range"] {
  accent-color: #00ff66 !important;
}
.MuiCheckbox-root.Mui-checked, .MuiRadio-root.Mui-checked,
.MuiSwitch-switchBase.Mui-checked, .MuiSlider-thumb {
  color: #00ff66 !important;
}
.MuiSlider-track, .MuiSlider-thumb, .MuiTabs-indicator {
  background-color: #00ff66 !important;
}

/* 7. Buttons. Green primary actions retain dark labels/icons. */
button, .MuiButton-root, [role="button"], [data-slot="button"] {
  font-family: Consolas, "Lucida Console", "Courier New", monospace !important;
  border-color: rgba(0, 255, 102, .32) !important;
}
button:hover, .MuiButton-root:hover, [role="button"]:hover,
[data-slot="button"]:hover {
  border-color: rgba(0, 255, 102, .61) !important;
  box-shadow: 0 0 9px rgba(0, 255, 102, .22) !important;
}
button[type="submit"], .MuiButton-containedPrimary,
[data-testid*="create-button"], [data-testid*="generate-button"],
[class*="createButton"], [class*="generateButton"],
button[class*="bg-pink"], button[class*="bg-purple"],
header a[href$="/create"], header a[href$="/studio"] {
  background-color: #00d653 !important;
  color: #001b06 !important;
  border: 1px solid #00ff66 !important;
  font-weight: bold !important;
  text-shadow: none !important;
  box-shadow: 0 0 10px rgba(0, 255, 102, .45) !important;
}
button[type="submit"]:hover, .MuiButton-containedPrimary:hover,
[data-testid*="create-button"]:hover, [data-testid*="generate-button"]:hover,
[class*="createButton"]:hover, [class*="generateButton"]:hover,
header a[href$="/create"]:hover, header a[href$="/studio"]:hover {
  background-color: #00ff66 !important;
  color: #001b06 !important;
  box-shadow: 0 0 16px rgba(0, 255, 102, .63) !important;
}
button[type="submit"] span, button[type="submit"] svg,
.MuiButton-containedPrimary span, .MuiButton-containedPrimary svg,
[class*="createButton"] span, [class*="createButton"] svg,
[class*="generateButton"] span, [class*="generateButton"] svg,
header a[href$="/create"] span, header a[href$="/studio"] span {
  color: #001b06 !important;
  text-shadow: none !important;
}

/* 8. Tab bars, badges, filters and selected choices. */
[role="tab"], .MuiTab-root, [data-slot="tabs-trigger"],
[class*="tabButton"], .MuiChip-root, [data-slot="badge"] {
  color: #95dba6 !important;
  border-color: rgba(0, 255, 102, .27) !important;
}
[role="tab"]:hover, .MuiTab-root:hover, [data-slot="tabs-trigger"]:hover {
  color: #00ff66 !important;
  background-color: rgba(0, 255, 102, .10) !important;
}
[role="tab"][aria-selected="true"], .MuiTab-root.Mui-selected,
[data-slot="tabs-trigger"][data-state="active"],
[role="option"][aria-selected="true"], [aria-checked="true"] {
  color: #00ff66 !important;
  border-color: #00ff66 !important;
}
.MuiChip-root, [data-slot="badge"], [role="status"] {
  background-color: rgba(0, 40, 16, .68) !important;
  border-color: rgba(0, 255, 102, .28) !important;
}

/* 9. Feed comments, tables, dividers and footer. */
[data-testid*="comment"], [data-testid*="chat-message"],
[class*="commentCard"], [class*="comment-card"],
[class*="messageBubble"], [class*="chatBubble"] {
  background-color: rgba(5, 29, 13, .72) !important;
  border-color: rgba(0, 255, 102, .25) !important;
  color: #b6ffc5 !important;
}
hr, .MuiDivider-root, [role="separator"], [data-slot="separator"] {
  border-color: rgba(0, 255, 102, .23) !important;
}
table, thead, tbody, tr, .MuiTable-root {
  background-color: transparent !important;
  color: #b6ffc5 !important;
}
th, td, .MuiTableCell-root {
  color: #b6ffc5 !important;
  border-color: rgba(0, 255, 102, .24) !important;
}
footer, [role="contentinfo"] {
  background-color: rgba(3, 20, 9, .78) !important;
  color: #9eeeb0 !important;
  border-color: rgba(0, 255, 102, .25) !important;
}

/* 10. Selection and dark terminal scrollbars. */
::selection { background-color: #00ff66 !important; color: #001b06 !important; }
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-track { background-color: #020c05; }
::-webkit-scrollbar-thumb { background-color: #236e3a; border: 2px solid #020c05; }
::-webkit-scrollbar-thumb:hover { background-color: #00b64c; }

/* 11. Generated artwork: NO color, brightness or blending changes. */
img, picture, video, canvas { mix-blend-mode: normal !important; }

main > section, main > article,
main > div > section, main > div > article,
[role="feed"], [role="feed"] > div,
[class*="feedLayout"], [class*="FeedLayout"],
[class*="feedWrapper"], [class*="FeedWrapper"],
[class*="feedContainer"], [class*="FeedContainer"],
[class*="feedColumn"], [class*="FeedColumn"] {
  background-color: rgba(3, 31, 14, .30) !important;
  border-color: rgba(0, 255, 102, .22) !important;
}
/* Individual posts and gallery cards. Include semantic roles and naming variants. */
main article, main [role="article"],
[role="feed"] > article, [role="feed"] [role="article"],
[data-testid*="feed"], [data-testid*="Feed"],
[data-testid*="post"], [data-testid*="Post"],
[class*="feedItem"], [class*="FeedItem"],
[class*="feedEntry"], [class*="FeedEntry"],
[class*="postItem"], [class*="PostItem"],
[class*="postContainer"], [class*="PostContainer"],
[class*="postContent"], [class*="PostContent"],
[class*="activityCard"], [class*="ActivityCard"],
[class*="creationTile"], [class*="CreationTile"],
[class*="galleryItem"], [class*="GalleryItem"],
[class*="imageTile"], [class*="ImageTile"] {
  background-color: rgba(4, 31, 14, .66) !important;
  color: #b6ffc5 !important;
  border-color: rgba(0, 255, 102, .38) !important;
  box-shadow: 0 5px 18px rgba(0, 0, 0, .24), inset 0 1px rgba(183, 255, 204, .08) !important;
}

main div[class*="bg-"][class*="rounded-"],
main div[class*="bg-"][class*="border-"],
main div[class*="bg-"][class*="shadow-"],
main section[class*="bg-"],
main article[class*="bg-"],
[role="feed"] div[class*="bg-"],
[role="feed"] section[class*="bg-"] {
  background-color: rgba(4, 30, 14, .57) !important;
  border-color: rgba(0, 255, 102, .33) !important;
}
/* Feed controls: filter/sort bars, comment areas, sidebars and card footers. */
[class*="feedHeader"], [class*="FeedHeader"],
[class*="feedFilter"], [class*="FeedFilter"],
[class*="filterBar"], [class*="FilterBar"],
[class*="sortBar"], [class*="SortBar"],
[class*="cardHeader"], [class*="CardHeader"],
[class*="cardFooter"], [class*="CardFooter"],
[class*="postHeader"], [class*="PostHeader"],
[class*="postFooter"], [class*="PostFooter"],
[class*="commentSection"], [class*="CommentSection"],
[class*="commentsContainer"], [class*="CommentsContainer"],
[class*="rightSidebar"], [class*="RightSidebar"],
[class*="rightRail"], [class*="RightRail"],
[class*="sideCard"], [class*="SideCard"],
.MuiCardHeader-root, .MuiCardContent-root, .MuiCardActions-root,
.MuiAccordionSummary-root, .MuiAccordionDetails-root,
.MuiList-root, .MuiListSubheader-root {
  background-color: rgba(4, 29, 13, .49) !important;
  color: #b6ffc5 !important;
  border-color: rgba(0, 255, 102, .25) !important;
}
/* Raised selectable filters / toolbar containers, with safe low-cost glow. */
main button[class*="bg-"],
main [role="button"][class*="bg-"],
main [role="tab"][class*="bg-"],
main [data-slot="button"][class*="bg-"] {
  background-color: rgba(4, 40, 18, .67) !important;
  border-color: rgba(0, 255, 102, .34) !important;
  color: #b6ffc5 !important;
}
main button[class*="bg-"]:hover,
main [role="button"][class*="bg-"]:hover,
main [role="tab"][class*="bg-"]:hover {
  background-color: rgba(0, 91, 36, .54) !important;
  color: #00ff66 !important;
}

[role="menu"], [role="listbox"], [role="dialog"],
.MuiMenu-paper, .MuiPopover-paper, .MuiDialog-paper,
[data-slot="dropdown-menu-content"], [data-slot="popover-content"],
[data-slot="dialog-content"], [data-slot="sheet-content"],
[class*="dropdownContent"], [class*="DropdownContent"],
[class*="menuContent"], [class*="MenuContent"] {
  background-color: rgba(3, 27, 12, .77) !important;
  border-color: rgba(0, 255, 102, .48) !important;
  -webkit-backdrop-filter: blur(9px) saturate(1.15) !important;
  backdrop-filter: blur(9px) saturate(1.15) !important;
}
/* Neon terminal lettering on feed details, without changing media pixels. */
main article a, main article time, main article small,
main [role="article"] a, main [role="article"] time,
main [role="article"] small, [role="feed"] p,
[role="feed"] label, [role="feed"] time {
  color: #b6ffc5 !important;
}
main article a:hover, main [role="article"] a:hover,
[role="feed"] a:hover {
  color: #00ff66 !important;
  text-shadow: 0 0 7px rgba(0, 255, 102, .38) !important;
}
/* Reassert the bright Create/Generate action after generic utility rules. */
button[type="submit"], .MuiButton-containedPrimary,
[data-testid*="create-button"], [data-testid*="generate-button"],
[class*="createButton"], [class*="generateButton"] {
  background-color: #00d653 !important;
  color: #001b06 !important;
  border-color: #00ff66 !important;
}
button[type="submit"] span, button[type="submit"] svg,
.MuiButton-containedPrimary span, .MuiButton-containedPrimary svg,
[class*="createButton"] span, [class*="createButton"] svg,
[class*="generateButton"] span, [class*="generateButton"] svg {
  color: #001b06 !important;
}

body div[class*="bg-"], body section[class*="bg-"],
body article[class*="bg-"], body aside[class*="bg-"],
body nav[class*="bg-"], body form[class*="bg-"],
body li[class*="bg-"], body a[class*="bg-"],
body button[class*="bg-"],
body div[style*="background"], body section[style*="background"],
body article[style*="background"], body aside[style*="background"],
body form[style*="background"], body a[style*="background"],
body button[style*="background"] {
  background-color: rgba(3, 38, 16, .56) !important;
  border-color: rgba(22, 255, 103, .34) !important;
}

main [class*="grid-cols-3"] > div,
main [class*="grid-cols-3"] > section,
main [class*="grid-cols-3"] > aside,
main [class*="grid-cols-12"] > div[class*="col-span"],
main [class*="grid-cols-12"] > section[class*="col-span"],
main [class*="grid-cols-12"] > aside,
main [class*="flex"] > div[class*="w-1/4"],
main [class*="flex"] > div[class*="w-1/3"],
main [class*="flex"] > div[class*="w-2/4"],
main [class*="flex"] > div[class*="w-2/3"],
main [class*="flex"] > div[class*="basis-1/4"],
main [class*="flex"] > div[class*="basis-1/3"],
main [class*="flex"] > div[class*="basis-1/2"],
main [class*="flex"] > div[class*="basis-2/3"],
main [class*="flex"] > aside,
main [class*="flex"] > section[class*="sidebar"],
main [class*="flex"] > section[class*="Sidebar"],
main aside, main [role="complementary"],
main [class*="leftSidebar"], main [class*="LeftSidebar"],
main [class*="rightSidebar"], main [class*="RightSidebar"],
main [class*="leftColumn"], main [class*="LeftColumn"],
main [class*="rightColumn"], main [class*="RightColumn"],
main [class*="centerColumn"], main [class*="CenterColumn"],
main [class*="feedColumn"], main [class*="FeedColumn"] {
  background-color: rgba(3, 35, 15, .34) !important;
  border: 1px solid rgba(0, 255, 102, .38) !important;
  border-radius: 12px !important;
  box-shadow: inset 0 1px 0 rgba(183, 255, 204, .07), 0 7px 20px rgba(0, 0, 0, .19) !important;
}

main article, main [role="article"],
main [data-slot="card"], main .MuiCard-root, main .MuiPaper-root,
main div[class*="rounded"][class*="bg-"],
main section[class*="rounded"][class*="bg-"],
main div[class*="rounded"][style*="background"],
main [class*="feedCard"], main [class*="FeedCard"],
main [class*="postCard"], main [class*="PostCard"],
main [class*="post-card"], main [class*="post-container"],
main [class*="postContainer"], main [class*="PostContainer"],
main [class*="composer"], main [class*="Composer"],
main [class*="createPost"], main [class*="CreatePost"],
main [class*="writePost"], main [class*="WritePost"],
main [class*="feedItem"], main [class*="FeedItem"],
main [class*="feedEntry"], main [class*="FeedEntry"],
main [class*="postItem"], main [class*="PostItem"] {
  background-color: rgba(3, 43, 18, .54) !important;
  border: 1px solid rgba(0, 255, 102, .40) !important;
  color: #b6ffc5 !important;
  box-shadow: inset 0 1px 0 rgba(183, 255, 204, .07), 0 5px 17px rgba(0, 0, 0, .19) !important;
}

main form,
main textarea, main [contenteditable="true"],
main [role="textbox"], main [role="combobox"],
main .MuiInputBase-root, main .MuiOutlinedInput-root,
main [data-slot="textarea"], main [data-slot="input"],
main [class*="postEditor"], main [class*="PostEditor"],
main [class*="postInput"], main [class*="PostInput"],
main [class*="commentInput"], main [class*="CommentInput"] {
  background-color: rgba(0, 23, 9, .70) !important;
  border-color: rgba(0, 255, 102, .50) !important;
  color: #bdffca !important;
}

aside a[href="/feed"], aside a[href$="/feed"],
[role="complementary"] a[href="/feed"],
[role="complementary"] a[href$="/feed"],
